"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3647],{36124:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a town prop and, on the client, turns on its info billboard.","params":[{"name":"propData","desc":"","lua_type":"PropBaseClass.PropData"}],"returns":[{"desc":"","lua_type":"Town"}],"function_type":"static","source":{"line":43,"path":"src/Shared/Class/Base/Props/Town.luau"}}],"properties":[],"types":[{"name":"Town","desc":"A Town adds no fields of its own; it is a [PropBaseClass] Prop.","lua_type":"PropBaseClass.Prop","source":{"line":35,"path":"src/Shared/Class/Base/Props/Town.luau"}}],"name":"Town","desc":"A town building on a player\'s base. Behaviourally it is a bare\\n[PropBaseClass] \u2014 no prompts, no timers, no state of its own \u2014 with one\\naddition: on the client it calls [PropBaseClass:ShowInfo], so a town always\\ndisplays its name and current level on a billboard above it.\\n\\nThat is the point of the class. Towns are upgrade targets rather than\\ninteractive props, so the only thing they need beyond the base behaviour is to\\nadvertise what level they are at.\\n\\nGated by [FeatureFlags].BaseEnabled \u2014 disabled by default; per-project forks\\nenable it deliberately.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","tags":["dormant"],"source":{"line":20,"path":"src/Shared/Class/Base/Props/Town.luau"}}')}}]);